   selected_={slots().front().value()};const auto box=grid_->bounds();auto surface=os::instance()->makeRgbaSurface(box.x2()+8,box.y2()+8);surface->clear();{ui::Graphics g(nullptr,surface,box.x,box.y);g.clipRect({0,0,box.w,box.h});paintSelection(g);}const auto area=skin_.selectionMaterialBounds(selectionBorder())&box;os::SurfaceLock lock(surface.get());int hits=0;for(int y=area.y;y<area.y2();++y)for(int x=area.x;x<area.x2();++x){const bool alpha=bool(surface->getPixel(x,y)>>24);require(alpha==borderHit({x,y}),"Resized tile selection rendered alpha and hit agree");hits+=alpha;}require(hits>0,"Resized selection has visible edge");
